var handlerCeldaSeleccionada = null;

self.onInit = function() {
    const $ctx = self.ctx;

    // Carga inicial (primera vez que se monta el widget)
    setTimeout(function() {
        repintarDesdeLocalStorage($ctx);
    }, 150);

    // El calendario avisa con este evento cada vez que se hace clic en una
    // celda nueva -- antes este widget solo leía localStorage UNA vez al
    // cargar, así que si cambiabas de celda sin recargar la página entera,
    // se quedaba con el primer día que se clicó. Ahora se repinta solo.
    handlerCeldaSeleccionada = function(e) {
        repintarDesdeLocalStorage($ctx, e.detail);
    };
    window.addEventListener('riego-celda-seleccionada', handlerCeldaSeleccionada);
};

// ============================================================
// Selector de fechas NATIVO de ThingsBoard (el del dashboard/widget de
// gráfica): esto SÍ dispara self.onDataUpdated, pero solo si el widget
// tiene al menos una clave configurada en la pestaña Data -- por eso hace
// falta añadir una (cualquiera, solo sirve de disparador). Cuando cambia
// la fecha, se pide por API el caudal de la entidad ya seleccionada
// (localStorage) para ESE día concreto.
// ============================================================
self.onDataUpdated = function() {
    const $ctx = self.ctx;
    if (!$ctx.timeWindow || !$ctx.timeWindow.minTime) return;

    const assetId = localStorage.getItem('riego_asset_id');
    if (!assetId || assetId === 'null') return;

    const fecha = new Date($ctx.timeWindow.minTime);
    const inicioDia = new Date(fecha.getFullYear(), fecha.getMonth(), fecha.getDate(), 0, 0, 0).getTime();
    const finDia = inicioDia + 86400000 - 1000;

    $ctx.$container.find('#v-fecha').text(
        String(fecha.getDate()).padStart(2, '0') + '/' +
        String(fecha.getMonth() + 1).padStart(2, '0') + '/' +
        fecha.getFullYear()
    );

    const hoy = new Date();
    const esHoy = (fecha.getFullYear() === hoy.getFullYear() && fecha.getMonth() === hoy.getMonth() && fecha.getDate() === hoy.getDate());

    const url = `/api/plugins/telemetry/ASSET/${assetId}/values/timeseries?keys=caudal_fijado,caudal_manual,media_proyectada&startTs=${inicioDia}&endTs=${finDia}&limit=200`;
    $ctx.http.get(url).subscribe(function(data) {
        // Misma prioridad que en el resto del sistema: manual > (si es hoy)
        // proyectada > fijado. Se toma el ultimo valor de cada lista.
        function ultimo(arr) {
            if (!arr || arr.length === 0) return null;
            return parseFloat(arr[arr.length - 1].value);
        }
        const manual = ultimo(data.caudal_manual);
        const proyectada = ultimo(data.media_proyectada);
        const fijado = ultimo(data.caudal_fijado);

        let valor = null;
        if (manual !== null && !isNaN(manual)) { valor = manual; }
        else if (esHoy && proyectada !== null && !isNaN(proyectada)) { valor = proyectada; }
        else if (fijado !== null && !isNaN(fijado)) { valor = fijado; }

        $ctx.$container.find('#v-caudal').text(valor !== null ? Math.round(valor) : '0');
        // El comentario no se recalcula aqui -- si tambien hace falta para
        // fechas distintas del clic original, dimelo y lo añado.
    }, function() {
        $ctx.$container.find('#v-caudal').text('0');
    });
};

function repintarDesdeLocalStorage($ctx, detalle) {
    // Si viene del evento ya trae los datos frescos; si no (carga inicial),
    // se leen de localStorage como se hacía siempre.
    const ts = detalle ? detalle.ts : localStorage.getItem('riego_ts');
    const nombre = detalle ? detalle.assetName : localStorage.getItem('riego_asset_name');
    const caudal = detalle ? detalle.caudal : localStorage.getItem('riego_caudal');
    const comentario = detalle ? detalle.comentario : localStorage.getItem('riego_comentario');

    if (nombre && nombre !== "null") {
        $ctx.$container.find('#v-nombre').text(nombre);
    }

    if (ts && ts !== "null" && !isNaN(parseInt(ts))) {
        const dateObj = new Date(parseInt(ts));
        const dia = String(dateObj.getDate()).padStart(2, '0');
        const mes = String(dateObj.getMonth() + 1).padStart(2, '0');
        const anio = dateObj.getFullYear();
        $ctx.$container.find('#v-fecha').text(dia + "/" + mes + "/" + anio);
    } else {
        $ctx.$container.find('#v-fecha').text("Día no seleccionado");
    }

    $ctx.$container.find('#v-caudal').text((caudal && caudal !== "null" && caudal !== "") ? caudal : "0");

    // La fila de Entidad/Fecha/Caudal NUNCA se mueve ni cambia de alto --
    // el comentario es un bloque aparte, debajo, que solo aparece si hay
    // algo que mostrar. Si es muy largo, tiene su propio scroll (el
    // "COMENTARIO:" y todo lo de arriba se quedan fijos en su sitio).
    if (comentario && comentario !== "null" && comentario.trim() !== "") {
        $ctx.$container.find('#v-comentario-texto').html(formatearComentario(comentario));
        $ctx.$container.find('#v-comentario-fila').css('display', 'block');
    } else {
        $ctx.$container.find('#v-comentario-fila').css('display', 'none');
    }
}

function escapeHtml(texto) {
    return texto
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;');
}

// El comentario puede traer varias partes juntas separadas por " | "
// (comentario del admin + nota del guarda). En cada parte, si viene con
// formato "Nombre: texto", el nombre se resalta en negrita para que se
// vea de un vistazo quién ha escrito qué.
function formatearComentario(comentario) {
    const partes = comentario.split(' | ');
    const partesHtml = partes.map(function(parte) {
        const idx = parte.indexOf(': ');
        if (idx === -1) { return escapeHtml(parte); }
        const nombre = parte.slice(0, idx);
        const resto = parte.slice(idx + 2);
        return '<b>' + escapeHtml(nombre) + ':</b> ' + escapeHtml(resto);
    });
    return partesHtml.join('<br>');
}

self.onDestroy = function() {
    if (handlerCeldaSeleccionada) {
        window.removeEventListener('riego-celda-seleccionada', handlerCeldaSeleccionada);
        handlerCeldaSeleccionada = null;
    }
};

